#!/usr/bin/env node
'use strict';

/**
 * Publish the trusted validator's verdict as a single, self-updating PR comment
 * and a small set of triage labels.
 *
 * Idempotent: the comment is located by an HTML marker and edited in place, so
 * repeated runs never spam the contributor. This bot never approves a pull
 * request - an automated comment is not a formal review.
 */

const fs = require('fs');
const os = require('os');
const path = require('path');
const { request, paginate, repoSlug } = require('./lib/github');

const BASE = repoSlug();
const PR = process.env.PR_NUMBER;
const MARKER = '<!-- catalog-validation-report -->';

const LABELS = {
  passed: { name: 'validation:passed', color: '0e8a16', description: 'Deterministic catalog validation passed' },
  failed: { name: 'validation:failed', color: 'd73a4a', description: 'Deterministic catalog validation failed' },
  human: { name: 'needs-human-review', color: 'fbca04', description: 'Requires a maintainer decision before merge' },
  conflict: { name: 'merge-conflict', color: 'b60205', description: 'Conflicts with the base branch' },
};

function readReport() {
  const candidates = [
    process.env.REPORT_PATH,
    PR ? path.join(process.env.RUNNER_TEMP || os.tmpdir(), `catalog-validation-${PR}.json`) : null,
  ].filter(Boolean);
  for (const p of candidates) {
    if (p && fs.existsSync(p)) return JSON.parse(fs.readFileSync(p, 'utf8'));
  }
  // The validator may have crashed before writing a report. Still publish an
  // actionable message instead of failing the reporting job too.
  return {
    repository: BASE,
    pr: Number(PR),
    title: '',
    author: '',
    headSha: '',
    valid: false,
    humanReview: false,
    humanReviewReasons: [],
    errors: ['The validator did not produce a report. This is a repository-side failure, not a problem with your PR. A maintainer will investigate.'],
    warnings: [],
    notes: [],
    files: [],
    added: [],
    removed: [],
  };
}

function buildBody(report) {
  const ok = report.valid;
  const lines = [];
  lines.push(MARKER);
  lines.push(`### ${ok ? 'Catalog validation passed' : 'Catalog validation failed'}`);
  lines.push('');
  lines.push('This is an automated data check, **not a formal review or approval**.');

  if (report.added && report.added.length) {
    lines.push('');
    lines.push('**Entries added**');
    for (const a of report.added) {
      lines.push(`- \`${a.file}\`: ${a.name ? `**${a.name}** ` : ''}(\`${a.id}\`)`);
    }
  }

  if (report.errors && report.errors.length) {
    lines.push('');
    lines.push(`**Errors (${report.errors.length})**`);
    for (const e of report.errors) lines.push(`- ${e}`);
  }

  if (report.warnings && report.warnings.length) {
    lines.push('');
    lines.push(`**Warnings (${report.warnings.length})**`);
    for (const w of report.warnings) lines.push(`- ${w}`);
  }

  if (report.humanReview && report.humanReviewReasons && report.humanReviewReasons.length) {
    lines.push('');
    lines.push('**Maintainer review required**');
    for (const r of report.humanReviewReasons) lines.push(`- ${r}`);
    lines.push('This PR will not be auto-merged.');
  }

  if (!ok) {
    lines.push('');
    lines.push('**How to fix**');
    lines.push('1. Edit the `*/catalog.json` file named in the errors above.');
    lines.push('2. Run `node .github/scripts/validate-catalogs.js` locally until it prints `All catalogs valid.`');
    lines.push('3. Push the commit; this check re-runs automatically.');
    lines.push('4. If the error is a merge conflict, merge `main` into your branch and resolve it.');
    if (report.errors && report.errors.some((e) => /generated README/i.test(e))) {
      lines.push('5. Regenerate docs with `node .github/scripts/generate-readme.js` and commit the result.');
    }
  }

  if (ok && !report.humanReview) {
    lines.push('');
    lines.push('A maintainer approval is still required. Once approved, auto-merge (squash) completes the merge automatically.');
  }

  lines.push('');
  lines.push(`<sub>Head ${String(report.headSha || '').slice(0, 12)} - generated by \`.github/scripts/pr-report.js\`</sub>`);
  return lines.join('\n');
}

async function upsertComment(number, body) {
  const comments = await paginate(`/repos/${BASE}/issues/${number}/comments`, { maxPages: 5, perPage: 100 });
  const existing = comments.find((c) => c && typeof c.body === 'string' && c.body.includes(MARKER));
  if (existing) {
    const { data } = await request(`/repos/${BASE}/issues/comments/${existing.id}`, { method: 'PATCH', body: { body } });
    console.log(`Updated existing validation comment ${existing.id}`);
    return data;
  }
  const { data } = await request(`/repos/${BASE}/issues/${number}/comments`, { method: 'POST', body: { body } });
  console.log(`Created validation comment ${data.id}`);
  return data;
}

async function ensureLabel(label) {
  const { status } = await request(`/repos/${BASE}/labels/${encodeURIComponent(label.name)}`, { allowStatus: [404] });
  if (status === 404) {
    await request(`/repos/${BASE}/labels`, { method: 'POST', body: label, allowStatus: [422] });
  }
}

async function setLabel(number, desired, opposites) {
  await ensureLabel(desired);
  await request(`/repos/${BASE}/issues/${number}/labels`, {
    method: 'POST',
    body: { labels: [desired.name] },
  });
  for (const other of opposites) {
    await request(`/repos/${BASE}/issues/${number}/labels/${encodeURIComponent(other)}`, {
      method: 'DELETE',
      allowStatus: [404],
    });
  }
}

async function main() {
  if (!PR) throw new Error('PR_NUMBER is required');
  const report = readReport();
  const number = String(PR);

  const comment = await upsertComment(number, buildBody(report));
  if (process.env.GITHUB_OUTPUT) fs.appendFileSync(process.env.GITHUB_OUTPUT, `comment_id=${comment.id}\n`);

  const hasConflict = (report.errors || []).some((e) => /merge conflict/i.test(e));

  if (report.valid) {
    await setLabel(number, LABELS.passed, [LABELS.failed.name]);
  } else {
    await setLabel(number, LABELS.failed, [LABELS.passed.name]);
  }

  if (report.humanReview) {
    await setLabel(number, LABELS.human, []);
  }
  if (hasConflict) {
    await setLabel(number, LABELS.conflict, []);
  }

  console.log(`Reported on PR #${number}: valid=${report.valid} humanReview=${report.humanReview}`);
}

main().catch((e) => {
  console.error(`Failed to publish validation report: ${e.message}`);
  process.exit(1);
});
